const names={overview:'Обзор стенда',tests:'Испытания',reports:'Отчётность',plugins:'Плагины оборудования',editors:'Редакторы',forms:'Формы и настройки'};
const blocks={overview:['Состояние стенда|Готов|6 из 6 компонентов','Активные испытания|2|ЯЛК · ЯТП','Последний verdict|ОК|05.09.2026 · 14:25','Профиль стенда|KTMA-01|v0.1.0-alpha'],tests:['Адаптер Ethernet / RS-485|Готов|ROKT · 204 bytes','В7-78/1|Готов|VISA · USB0::…TW00053184','ИСД|Готов|HTTP · type=5 · bus=1','Р4831|Ввод оператора|Ручная операция · 120 Ом'],reports:['ЯЛК-96 · ТУ 5.6|ОК|1788608801210-6c94b158','ЯТП · 120 Ом|НЕ ОК|1788607714095-82eed2b'],plugins:['Ethernet / RS-485 адаптер|Готов|orbita.ulk_rokt · реальное оборудование','ИСД|Готов|orbita.isd_http · реальное оборудование','В7-78/1|Готов|measure.reference_voltage · VISA','Р4831|Нужен ввод|manual.resistance · ручной источник'],editors:['YAML синтаксис|Корректен|Черновик сценария v5.6.2-draft','Привязки|Подтверждены|Адреса калибровки 97 / 99','Публикация|Защищена|Опубликованный файл неизменяем'],forms:['Профиль стенда|KTMA-01|192.168.0.50 · порт 1113','Ручной ввод Р4831|120.00 Ом|Значение попадёт в протокол','Права доступа|3 роли|Оператор · Инженер · Администратор']};
function card(x){let [a,b,d]=x.split('|');let cls=/ОК|Готов|Корректен|Подтверждены|KTMA/.test(b)?'ok':/НЕ ОК|Ввод|Нужен/.test(b)?'warn':'';return `<div class="card"><div class="label">${a}</div><div class="metric ${cls}">${b}</div><div class="label">${d}</div></div>`}
function render(k){document.querySelector('#title').textContent=names[k];document.querySelector('#crumb').textContent=names[k];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.screen===k));let html=`<div class="screen"><div class="grid g4">${blocks[k].map(card).join('')}</div><div class="head"><h2>${names[k]}</h2><button class="btn" id="primary">${k==='tests'?'Проверить готовность':k==='reports'?'Экспорт CSV':k==='editors'?'Проверить черновик':'Открыть раздел'}</button></div><div class="card"><h3>${k==='overview'?'Маршрут проверки':k==='tests'?'Готовность стенда':k==='reports'?'Запуски и отчёты':k==='plugins'?'Capability и диагностика':k==='editors'?'Черновик сценария':'Настройки и права доступа'}</h3><p class="label">${k==='overview'?'Объект → ячейка → процедура → готовность → запуск → измерения → итог → отчёт':k==='tests'?'ЯЛК: калибровка 97/99 → 0 / 3,1 / 6,2 В → 16 fresh samples':k==='reports'?'HTML · CSV · PDF-ready · версии сценария, каталога и профиля стенда':k==='plugins'?'Реальные и симулированные устройства отображаются раздельно.':k==='editors'?'id: ubsi.yalk.tu5_6 · steps: calibration / voltage / samples': 'Операторский, инженерский и административный уровни доступа.'}</p><div class="progress"><i style="width:${k==='tests'?68:100}%"></i></div><p class="ok">● Данные готовы для просмотра</p></div></div>`;document.querySelector('#content').innerHTML=html;document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>render(b.dataset.screen));let p=document.querySelector('#primary');if(p)p.onclick=()=>{p.textContent='Готово · ОК';p.classList.add('secondary')}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>render(b.dataset.screen));document.querySelector('#theme').onclick=()=>document.body.classList.toggle('dark');document.querySelector('#role').onchange=e=>e.target.value==='Оператор'?document.body.classList.add('dark'):document.body.classList.remove('dark');render('overview');
